import 'package:flutter/material.dart';

void main() {
  runApp(MyApp());
}

class MyApp extends StatelessWidget {
  @override
  Widget build(BuildContext context) {
    return MaterialApp(
      title: 'Style OS',
      theme: ThemeData(
        primarySwatch: Colors.blue,
      ),
      home: MobileHomeScreen(),
    );
  }
}

class MobileHomeScreen extends StatelessWidget {
  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(
        title: Text('Style OS'),
      ),
      body: ListView(
        padding: EdgeInsets.all(16.0),
        children: [
          // Closet Health & Wardrobe Analytics
          SectionTile(
            title: 'Closet Health & Audit',
            subtitle: 'Style OS Sartorial Intelligence',
            content: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Text('Closet Health', style: TextStyle(fontSize: 20, fontWeight: FontWeight.bold)),
                SizedBox(height: 8),
                Text('Real-time dynamic wardrobe efficiency', style: TextStyle(fontSize: 14, color: Colors.grey)),
                SizedBox(height: 16),
                Row(
                  mainAxisAlignment: MainAxisAlignment.spaceBetween,
                  children: [
                    Column(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: [
                        Text('88%', style: TextStyle(fontSize: 20, fontWeight: FontWeight.bold)),
                        SizedBox(height: 4),
                        Text('Score', style: TextStyle(fontSize: 12, color: Colors.grey)),
                      ],
                    ),
                    Container(
                      width: 60,
                      height: 60,
                      decoration: BoxDecoration(
                        shape: BoxShape.circle,
                        border: Border.all(color: Color(0xFFE9ECEF), width: 2),
                      ),
                      child: Center(
                        child: CircularProgressIndicator(
                          value: 0.88,
                          backgroundColor: Colors.white,
                          valueColor: AlwaysStoppedAnimation<Color>(Color(0xFF0070EA)),
                          strokeWidth: 4,
                        ),
                      ),
                    ),
                  ],
                ),
              ],
            ),
          ),

          // Wardrobe Gaps
          SectionTile(
            title: 'Wardrobe Gaps',
            subtitle: '',
            content: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Text('2 Identified', style: TextStyle(fontSize: 14, color: Colors.blue)),
                SizedBox(height: 8),
                Row(
                  children: [
                    Container(
                      width: 60,
                      height: 60,
                      decoration: BoxDecoration(
                        shape: BoxShape.circle,
                        image: DecorationImage(image: NetworkImage('https://example.com/trench_coat.jpg'), fit: BoxFit.cover),
                      ),
                    ),
                    SizedBox(width: 16),
                    Column(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: [
                        Text('Breathable Spring Trench', style: TextStyle(fontSize: 18, fontWeight: FontWeight.bold)),
                        SizedBox(height: 4),
                        Text('Unlocks 6 business casual combinations for 65°F–75°F forecast.', style: TextStyle(fontSize: 12, color: Colors.grey)),
                      ],
                    ),
                  ],
                ),
              ],
            ),
          ),

          // Dormant Items
          SectionTile(
            title: 'Dormant Items',
            subtitle: '>45 days without closet rotation',
            content: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Text('5 Pieces ($640)', style: TextStyle(fontSize: 14, color: Colors.red)),
                SizedBox(height: 8),
                Container(
                  height: 200,
                  child: ListView.builder(
                    scrollDirection: Axis.horizontal,
                    itemCount: 3,
                    itemBuilder: (context, index) {
                      return Padding(
                        padding: const EdgeInsets.all(8.0),
                        child: Container(
                          width: 120,
                          decoration: BoxDecoration(
                            color: Colors.grey[200],
                            borderRadius: BorderRadius.circular(8),
                          ),
                          child: Center(
                            child: Text('Item $index'),
                          ),
                        ),
                      );
                    },
                  ),
                ),
              ],
            ),
          ),

          // Category Utilization
          SectionTile(
            title: 'Category Utilization',
            subtitle: 'Last 45 Days',
            content: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Row(
                  mainAxisAlignment: MainAxisAlignment.spaceBetween,
                  children: [
                    Text('Outerwear', style: TextStyle(fontSize: 16, fontWeight: FontWeight.bold)),
                    LinearProgressIndicator(value: 0.92),
                  ],
                ),
                SizedBox(height: 8),
                Row(
                  mainAxisAlignment: MainAxisAlignment.spaceBetween,
                  children: [
                    Text('Tops & Shirts', style: TextStyle(fontSize: 16, fontWeight: FontWeight.bold)),
                    LinearProgressIndicator(value: 0.86),
                  ],
                ),
                SizedBox(height: 8),
                Row(
                  mainAxisAlignment: MainAxisAlignment.spaceBetween,
                  children: [
                    Text('Bottoms & Tailoring', style: TextStyle(fontSize: 16, fontWeight: FontWeight.bold)),
                    LinearProgressIndicator(value: 0.90),
                  ],
                ),
                SizedBox(height: 8),
                Row(
                  mainAxisAlignment: MainAxisAlignment.spaceBetween,
                  children: [
                    Text('Footwear', style: TextStyle(fontSize: 16, fontWeight: FontWeight.bold)),
                    LinearProgressIndicator(value: 0.78),
                  ],
                ),
              ],
            ),
          ),

          // Economic & Eco Impact
          SectionTile(
            title: 'Economic & Eco Impact',
            subtitle: '',
            content: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Text('ⓘ $230 Saved This Quarter', style: TextStyle(fontSize: 16, fontWeight: FontWeight.bold)),
                SizedBox(height: 8),
                Text('Achieved by maximizing existing wardrobe rotations and reducing redundant fast-fashion impulse acquisitions.', style: TextStyle(fontSize: 14, color: Colors.grey)),
              ],
            ),
          ),
        ],
      ),
    );
  }
}

class SectionTile extends StatelessWidget {
  final String title;
  final String subtitle;
  final Widget content;

  SectionTile({required this.title, required this.subtitle, required this.content});

  @override
  Widget build(BuildContext context) {
    return Card(
      elevation: 4,
      child: Padding(
        padding: const EdgeInsets.all(16.0),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Row(
              mainAxisAlignment: MainAxisAlignment.spaceBetween,
              children: [
                Text(title, style: TextStyle(fontSize: 20, fontWeight: FontWeight.bold)),
                subtitle.isNotEmpty ? Text(subtitle, style: TextStyle(fontSize: 14, color: Colors.grey)) : Container(),
              ],
            ),
            SizedBox(height: 8),
            content,
          ],
        ),
      ),
    );
  }
}
